sp_widget.client_script:
api.controller = function($scope, $rootScope, spUtil, spAriaUtil) {
	var c= this;
	$scope.accessibilityModeEnabled = spAriaUtil.isAccessibilityEnabled();

	c.selectView = function () {
		$rootScope.selectedView = c.options.view;
		$rootScope.$broadcast('selectedView', c.options.view);
	}

}

sp_widget.css:
/* General button style */
$secondary-color: #000000;
//==Backgrounds
$background-primary: #ffffff; //--now-color_background--primary
$background-secondary: #f8f6f6; //--now-color_background--secondary
$background-tertiary: #F5F0F1; //--now-color_background--tertiary

//==borders
$border-primary: #8790A1; //--now-color_border--primary
$border-secondary: #BEACB2; //--now-color_border--secondary
$border-tertiary: #E2DADD; //--now-color_border--tertiary

$brand-primary: #c31a1f; //--now-color--primary-1
$brand-danger: #E42338; //--now-color_alert--critical-2
$brand-warning: #F0E000; //--now-color_alert--warning-2
$brand-moderate: #8B6BFF; //--now-color_alert--moderate-2 NEW
$brand-low: #9698A4; //--now-color_alert--low-2 NEW
$brand-success: #51ae00; //--now-color_alert--positive-2
$brand-info: #38aaf4; //--now-color_alert--info-2

.div_image {
  display: inline-block;
  width:60px;
}

button[disabled]  {
  opacity: .5;
  background-color: $background-primary;
}

.btn-sep .disabled {
  background-color: $background-primary;
}

.btn {
  vertical-align: middle;

  font-family: 'Lato';
  font-size: inherit;
  color: inherit;
  background: none;
  cursor: pointer;
  display: inline-block;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 700;
  outline: none;
  position: relative;
  -webkit-transition: all 0.3s;
  -moz-transition: all 0.3s;
  transition: all 0.3s;
}

/* Icon separator */
.btn-sep {
  padding: 25px 60px 25px 60px;
  background: $brand-primary;
  border:none;
}

.btn-sep:before {
  background: rgba(0,0,0,0.15);
}

/* Button 1 */
.btn-1 {
  --f: 1.15;
  background: $brand-primary;
  color: #fff;
  opacity: 0.75;

  &:hover {
	clip-path: inset(calc((1 - 1/var(--f)) * 50%));
  scale: var(--f);
  opacity: 1;
  }

  &:active { 
   outline: none;
	box-shadow: 0 0;
  scale: var(--f);
  opacity: 1;
  }
}

.btn-1:hover {
  background: $brand-primary;
}

.btn-1:active {
  background: $brand-primary;
  top: 2px;
}

sp_widget.script:
(function(){
	var gr = $sp.getInstanceRecord();
	var img = new GlideRecord('db_image');
	img.addQuery('sys_id', options.image);
	img.query();
	if (img.next()){
		data.image = img.getValue('name');
	}
	data.btn_label = gs.getMessage(options.label);

	data.displayIconLink = (options.view==1) || ((options.view==3 || options.view==2) && checkIfManager(gs.getUserID()));

	console.log('options.view: ' + options.view);
	console.log('checkIfManager(gs.getUserID()): ' + checkIfManager(gs.getUserID()));

	function checkIfManager(inUser) {
		var retValue = false;
		var grSysUser = new GlideRecord('sys_user');
		grSysUser.addEncodedQuery("manager=" + inUser + "^active=true");
		grSysUser.query();
		if(grSysUser.getRowCount() > 0) {
			retValue = true
		}

		return retValue;
	}


})();
